package site

import (
	"context"
	"github.com/0xJacky/Nginx-UI/internal/event"
	"github.com/0xJacky/Nginx-UI/internal/nginx"
	"github.com/0xJacky/Nginx-UI/model"
)

// Disable disables a site by removing the symlink in sites-enabled. A site
// generated by an ingress is refused unless the Force option is given.
func Disable(ctx context.Context, name string, opts ...MutateOption) (err error) {
	enabledConfigFilePath, err := resolveEnabledSymlinkPath(name)
	if err != nil {
		return err
	}
	if err = CheckManaged(name, opts...); err != nil {
		return err
	}

	// Remote namespaces keep their deployment intent in the database because no
	// local symlink is ever created for them.
	if IsRemoteDeploy(name) {
		if err = setRemoteEnabled(name, false); err != nil {
			return
		}

		if err = syncDisable(ctx, name); err != nil {
			return err
		}
		event.PublishSiteDisabled(name)

		return
	}

	// Already disabled: keep the operation idempotent so cluster syncs can
	// converge a node without reporting spurious failures.
	enabledExists, err := nginx.Exists(enabledConfigFilePath)
	if err != nil {
		return err
	}
	if !enabledExists {
		return syncDisable(ctx, name)
	}

	err = nginx.Remove(enabledConfigFilePath)
	if err != nil {
		return
	}

	// Keep the certificate records so the certificates stay reusable; only
	// their renewal pauses until the configuration is enabled again.
	err = model.PauseAutoCert(name)
	if err != nil {
		return
	}

	res := nginx.Control(nginx.Reload)
	if res.IsError() {
		return res.GetError()
	}

	if err = syncDisable(ctx, name); err != nil {
		return err
	}
	event.PublishSiteDisabled(name)

	return
}

func syncDisable(ctx context.Context, name string) error {
	return syncFinalState(ctx, name, "disable")
}
